import{_ as e,c as o,o as r,ae as i}from"./chunks/framework.CliRSA9F.js";const u=JSON.parse('{"title":"The PodSEO Workflow","description":"","frontmatter":{},"headers":[],"relativePath":"getting-started/workflow.md","filePath":"getting-started/workflow.md"}'),s={name:"getting-started/workflow.md"};function n(a,t,d,l,g,h){return r(),o("div",null,[...t[0]||(t[0]=[i('<h1 id="the-podseo-workflow" tabindex="-1">The PodSEO Workflow <a class="header-anchor" href="#the-podseo-workflow" aria-label="Permalink to &quot;The PodSEO Workflow&quot;">​</a></h1><h2 id="from-strategy-to-optimized-episodes" tabindex="-1">From Strategy to Optimized Episodes <a class="header-anchor" href="#from-strategy-to-optimized-episodes" aria-label="Permalink to &quot;From Strategy to Optimized Episodes&quot;">​</a></h2><p>This guide walks you through the complete PodSEO workflow — from defining your podcast&#39;s positioning to publishing optimized episodes and monitoring results. Follow these steps to systematically improve your podcast&#39;s discoverability across Apple Podcasts, Spotify, Amazon Music, and YouTube Music.</p><h2 id="understanding-the-two-planning-horizons" tabindex="-1"><strong>Understanding the Two Planning Horizons</strong> <a class="header-anchor" href="#understanding-the-two-planning-horizons" aria-label="Permalink to &quot;**Understanding the Two Planning Horizons**&quot;">​</a></h2><p>Before diving into the steps, it&#39;s important to understand how PodSEO organizes your strategy:</p><ul><li><strong>Positioning</strong> is your long-term plan. Think of it as a season-level or multi-season direction — who you serve, what you cover, and how you&#39;re different. Review it infrequently and only change it when your show&#39;s direction evolves.</li><li><strong>Keyword Strategy</strong> is your medium-term plan. It should span roughly 5-10 episodes, giving you enough time to monitor the effects of your optimization before adjusting. Keywords are the tactical layer on top of your positioning.</li></ul><hr><h2 id="step-1-review-your-positioning-strategy" tabindex="-1"><strong>Step 1: Review Your Positioning Strategy</strong> <a class="header-anchor" href="#step-1-review-your-positioning-strategy" aria-label="Permalink to &quot;**Step 1: Review Your Positioning Strategy**&quot;">​</a></h2><p>When you first add your podcast, PodSEO imports basic positioning information from your feed. Your first task is to review and refine this.</p><p><strong>Where</strong>: Go to <strong>Command Center</strong> → <strong>Positioning</strong></p><p><strong>What to do</strong>:</p><ul><li>Check that your target audience, key subjects, and unique angle are filled in accurately</li><li>Ensure your positioning reflects what makes your podcast distinctive</li><li>The more accurate your positioning, the better PodSEO&#39;s AI suggestions will be across the platform</li></ul><p><strong>Why it matters</strong>: Your positioning statement is used by the <a href="/features/planner.html">AI Producer</a>, <a href="/features/pulse.html">Pulse</a>, and other AI features to generate relevant suggestions. Vague or inaccurate positioning leads to generic recommendations.</p><hr><h2 id="step-2-review-your-competitors" tabindex="-1"><strong>Step 2: Review Your Competitors</strong> <a class="header-anchor" href="#step-2-review-your-competitors" aria-label="Permalink to &quot;**Step 2: Review Your Competitors**&quot;">​</a></h2><p>Competitors are the benchmark against which PodSEO measures your performance and identifies opportunities. The more relevant your competitors, the more useful every insight becomes.</p><p><strong>Where</strong>: Click <strong>Competition</strong> in the sidebar</p><p><strong>What to do</strong>:</p><ul><li>Review the competitors PodSEO has identified through <a href="/features/competitor-finder.html">Competitor Finder</a></li><li>Add competitors you know about that may not have been detected automatically</li><li>Remove any that aren&#39;t truly competing for the same audience</li><li>Check the <a href="/features/competitive-analysis.html">Competitive Analysis</a> to see how you compare</li></ul><p><strong>Why it matters</strong>: Competitor data feeds into content gap analysis in the AI Producer, keyword opportunity suggestions, and the insights that appear on your <a href="/features/command-center.html">Command Center</a>.</p><hr><h2 id="step-3-build-your-keyword-strategy" tabindex="-1"><strong>Step 3: Build Your Keyword Strategy</strong> <a class="header-anchor" href="#step-3-build-your-keyword-strategy" aria-label="Permalink to &quot;**Step 3: Build Your Keyword Strategy**&quot;">​</a></h2><p>Your keyword strategy is the core of SEO optimization. It tells PodSEO which keywords to optimize for, track, and measure.</p><p><strong>Where</strong>: Click <strong>Search Visibility</strong> in the sidebar</p><p><strong>What to do</strong>:</p><h3 id="find-keywords" tabindex="-1"><strong>Find Keywords</strong> <a class="header-anchor" href="#find-keywords" aria-label="Permalink to &quot;**Find Keywords**&quot;">​</a></h3><ul><li><strong>AI Suggestions</strong>: Use the AI tab in Keyword Strategy to discover keywords recommended based on your podcast&#39;s content</li><li><strong>Free-form</strong>: Add keywords manually that you believe your audience searches for</li><li><strong>Organic Visibility</strong>: Look at <a href="/features/show-visibility.html">Show Visibility</a> for keywords you already rank for — these are potential quick wins</li></ul><h3 id="prioritize-keywords" tabindex="-1"><strong>Prioritize Keywords</strong> <a class="header-anchor" href="#prioritize-keywords" aria-label="Permalink to &quot;**Prioritize Keywords**&quot;">​</a></h3><ul><li>Set <strong>2-3 Primary keywords</strong> — these drive show-level metadata optimization (title, description). They&#39;re your main targets.</li><li>Add <strong>Secondary keywords</strong> — these influence episode-level optimization and provide supporting signals</li><li>Keep promising keywords as <strong>Monitored</strong> — track them without actively optimizing yet</li></ul><h3 id="look-for-low-hanging-fruit" tabindex="-1"><strong>Look for Low-Hanging Fruit</strong> <a class="header-anchor" href="#look-for-low-hanging-fruit" aria-label="Permalink to &quot;**Look for Low-Hanging Fruit**&quot;">​</a></h3><p>Check your organic visibility for keywords where you rank near the top (positions 6-15). These are the easiest wins — a small optimization push could move them into high-visibility positions.</p><p><strong>Rule of thumb</strong>: Primary keywords matter most for your show-level metadata (title, author, description). Secondary keywords are more relevant for individual episode optimization.</p><hr><h2 id="step-4-plan-and-optimize-in-the-planner" tabindex="-1"><strong>Step 4: Plan and Optimize in the Planner</strong> <a class="header-anchor" href="#step-4-plan-and-optimize-in-the-planner" aria-label="Permalink to &quot;**Step 4: Plan and Optimize in the Planner**&quot;">​</a></h2><p>With your positioning, competitors, and keywords set, the Planner becomes your operational hub.</p><p><strong>Where</strong>: Go to <strong>Command Center</strong> → <strong>Planner</strong></p><h3 id="check-metadata-alignment" tabindex="-1"><strong>Check Metadata Alignment</strong> <a class="header-anchor" href="#check-metadata-alignment" aria-label="Permalink to &quot;**Check Metadata Alignment**&quot;">​</a></h3><p>The Metadata/Keyword Alignment card at the top of the Planner shows how well your current metadata matches your Primary keyword strategy. Review the scores for title, author, description, and episodes.</p><p>Click <strong>&quot;Get AI suggestions to improve&quot;</strong> to receive specific recommendations for improving your alignment scores. Implement these changes in your podcast hosting platform.</p><h3 id="review-published-episodes" tabindex="-1"><strong>Review Published Episodes</strong> <a class="header-anchor" href="#review-published-episodes" aria-label="Permalink to &quot;**Review Published Episodes**&quot;">​</a></h3><p>Browse your published episodes on the Board to see which ones are optimized for your keyword strategy. You can analyze any episode individually — not just recent ones.</p><h3 id="plan-new-episodes" tabindex="-1"><strong>Plan New Episodes</strong> <a class="header-anchor" href="#plan-new-episodes" aria-label="Permalink to &quot;**Plan New Episodes**&quot;">​</a></h3><p>Use the <strong>AI Producer</strong> tab to discover new episode topics:</p><ul><li><strong>Trending topics</strong> in your niche</li><li><strong>Content gaps</strong> vs. your competitors</li><li><strong>Keyword opportunities</strong> based on your strategy</li></ul><p>When you find a promising topic, add it to your Board with a single click.</p><hr><h2 id="step-5-produce-optimized-episodes" tabindex="-1"><strong>Step 5: Produce Optimized Episodes</strong> <a class="header-anchor" href="#step-5-produce-optimized-episodes" aria-label="Permalink to &quot;**Step 5: Produce Optimized Episodes**&quot;">​</a></h2><p>As you work on episodes, PodSEO helps you optimize them for discoverability.</p><p><strong>Where</strong>: <strong>Planner</strong> → <strong>Board</strong></p><p><strong>What to do</strong>:</p><ol><li>Move an episode card from <strong>Ideas</strong> to <strong>In Progress</strong></li><li>Ask PodSEO for <strong>AI-powered title and description suggestions</strong> aligned with your keyword strategy</li><li>Implement the suggestions while maintaining your authentic voice — natural keyword integration is key</li><li>Publish the episode and move the card to <strong>Published</strong></li></ol><p><strong>Best practice</strong>: Don&#39;t keyword-stuff. Platforms penalize obvious over-optimization. Focus on incorporating keywords naturally into titles and descriptions that are genuinely compelling to listeners.</p><hr><h2 id="step-6-monitor-and-iterate" tabindex="-1"><strong>Step 6: Monitor and Iterate</strong> <a class="header-anchor" href="#step-6-monitor-and-iterate" aria-label="Permalink to &quot;**Step 6: Monitor and Iterate**&quot;">​</a></h2><p>After publishing, track how your optimization efforts perform and adjust your strategy based on results.</p><p><strong>Where</strong>: Click <strong>Search Visibility</strong> in the sidebar</p><h3 id="track-rankings" tabindex="-1"><strong>Track Rankings</strong> <a class="header-anchor" href="#track-rankings" aria-label="Permalink to &quot;**Track Rankings**&quot;">​</a></h3><p>Use <a href="/features/keyword-tracker.html">Keyword Tracker</a> to monitor how your rankings change after optimization:</p><ul><li><strong>Initial changes</strong>: 1-2 weeks after publishing</li><li><strong>Significant improvements</strong>: 2-4 weeks</li><li><strong>Full impact</strong>: 4-8 weeks</li></ul><h3 id="check-visibility-progress" tabindex="-1"><strong>Check Visibility Progress</strong> <a class="header-anchor" href="#check-visibility-progress" aria-label="Permalink to &quot;**Check Visibility Progress**&quot;">​</a></h3><p>Visit <strong>Traction</strong> → <a href="/features/visibility-progress.html">Visibility Progress</a> to see how your overall visibility score trends over time.</p><h3 id="iterate-on-your-strategy" tabindex="-1"><strong>Iterate on Your Strategy</strong> <a class="header-anchor" href="#iterate-on-your-strategy" aria-label="Permalink to &quot;**Iterate on Your Strategy**&quot;">​</a></h3><p>After 5-10 episodes with a given keyword strategy:</p><ul><li><strong>Graduate successful keywords</strong>: Move Primary keywords that have reached strong positions to Secondary (maintenance mode)</li><li><strong>Promote new keywords</strong>: Bring Monitored keywords up to Primary for the next cycle</li><li><strong>Adjust based on results</strong>: If certain keywords aren&#39;t moving despite optimization, consider whether they&#39;re too competitive or not well-matched to your content</li></ul><hr><h2 id="the-ongoing-cycle" tabindex="-1"><strong>The Ongoing Cycle</strong> <a class="header-anchor" href="#the-ongoing-cycle" aria-label="Permalink to &quot;**The Ongoing Cycle**&quot;">​</a></h2><p>Podcast SEO is iterative. Each cycle follows this pattern:</p><ol><li><strong>Define</strong> → Set your keyword strategy (5-10 episode horizon)</li><li><strong>Optimize</strong> → Use the Planner to align metadata and plan episodes</li><li><strong>Produce</strong> → Create episodes with optimized titles and descriptions</li><li><strong>Monitor</strong> → Track rankings and visibility in Search Visibility</li><li><strong>Adapt</strong> → Rotate keywords, adjust strategy, start the next cycle</li></ol><p>Your positioning provides the steady foundation. Your keyword strategy provides the tactical focus. The Planner ties them together into actionable episode plans.</p><hr><h2 id="quick-reference-where-to-find-things" tabindex="-1"><strong>Quick Reference: Where to Find Things</strong> <a class="header-anchor" href="#quick-reference-where-to-find-things" aria-label="Permalink to &quot;**Quick Reference: Where to Find Things**&quot;">​</a></h2><table tabindex="0"><thead><tr><th>What you need</th><th>Where to go</th></tr></thead><tbody><tr><td>Daily status and priorities</td><td><strong>Command Center</strong></td></tr><tr><td>Episode planning and metadata optimization</td><td><strong>Command Center</strong> → <strong>Planner</strong></td></tr><tr><td>Long-term show positioning</td><td><strong>Command Center</strong> → <strong>Positioning</strong></td></tr><tr><td>Trending topics for episodes</td><td><strong>Command Center</strong> → <strong>Pulse</strong></td></tr><tr><td>Keyword management</td><td><strong>Search Visibility</strong></td></tr><tr><td>Ranking tracking</td><td><strong>Search Visibility</strong> → <strong>Keyword Tracker</strong></td></tr><tr><td>Competitor insights</td><td><strong>Competition</strong></td></tr><tr><td>AI platform visibility</td><td><strong>AI Visibility</strong></td></tr><tr><td>Editorial and PR tracking</td><td><strong>PR &amp; Media Coverage</strong></td></tr><tr><td>Chart positions</td><td><strong>Charts</strong></td></tr><tr><td>AI chat assistant</td><td><strong>Chat</strong> (sidebar)</td></tr></tbody></table><hr><h2 id="next-steps" tabindex="-1"><strong>Next Steps</strong> <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;**Next Steps**&quot;">​</a></h2><p>Once you&#39;ve mastered the core workflow, explore these features for deeper insights:</p><ul><li><strong><a href="/features/competitive-analysis.html">Competitive Analysis</a></strong> — Compare your podcast with competitors in detail</li><li><strong><a href="/features/ai-mentions.html">AI Mentions</a></strong> — Track your visibility on AI platforms</li><li><strong><a href="/features/my-placements.html">Editorial Presence</a></strong> — Monitor editorial features and web mentions</li><li><strong><a href="/features/lucia-ai-assistant.html">LUCIA AI Chat</a></strong> — Ask questions and get expert guidance</li></ul><p>For more help, check out our <a href="/getting-started/first-steps.html">Getting Started guide</a> or browse the complete feature documentation.</p>',77)])])}const c=e(s,[["render",n]]);export{u as __pageData,c as default};
